export function normalizeLanguage(value) {
  const code = String(value || '').toLowerCase().split(/[-_]/)[0];
  return dictionaries[code] ? code : 'en';
}

export function detectDeviceLanguage() {
  try { return normalizeLanguage(navigator.language || navigator.languages?.[0] || 'en'); }
  catch { return 'en'; }
}

export function localeForLanguage(language) {
  return LANGUAGES.find((item) => item.code === normalizeLanguage(language))?.locale || 'en-US';
}

export function translate(language, key, vars = {}) {
  const lang = normalizeLanguage(language);
  const template = dictionaries[lang]?.[key] ?? en[key] ?? key;
  return String(template).replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? `{${name}}`);
}
